use std::collections::HashMap;

/// Counts the frequency of each word in the input string.
///
/// Words are split on whitespace and normalized to lowercase.
/// Punctuation attached to words is stripped from the start and end.
pub fn word_frequencies(text: &str) -> HashMap<String, usize> {
    let mut counts = HashMap::new();

    for word in text.split_whitespace() {
        // Trim leading/trailing punctuation and lowercase the word.
        let cleaned: String = word
            .trim_matches(|c: char| !c.is_alphanumeric())
            .to_lowercase();

        if !cleaned.is_empty() {
            *counts.entry(cleaned).or_insert(0) += 1;
        }
    }

    counts
