            // Skip non-alphanumeric characters on the right
            if (!Character.isLetterOrDigit(rc)) {
                right--;
                continue;
            }

            // Compare characters case-insensitively
            if (Character.toLowerCase(lc) != Character.toLowerCase(rc)) {
                return false;
            }

            left++;
            right--;
        }

